import { eventFacts, eventPage, eventOrdinal, plainEvent } from './facts.js';
import { contractInterface, ChainDataError, checkAbort, decodeLog } from './client.js';
import { playerAddress, uint } from './state.js';

export const BOX_RESULTS = ['LootBoxOpened', 'PresaleBoxOpened', 'LootBoxDgnrsBatch', 'LootBoxWhalePassJackpot', 'LootBoxReward', 'LootBoxCrapsPasses', 'BoxSpin'];
const RESULT_TYPES = { LootBoxOpened: 'opened', PresaleBoxOpened: 'presale_opened' };
const LEG_TYPES = { LootBoxOpened: 'opened', PresaleBoxOpened: 'presale', LootBoxDgnrsBatch: 'dgnrs', LootBoxWhalePassJackpot: 'whalepass', LootBoxReward: 'reward', LootBoxCrapsPasses: 'crapsPasses', BoxSpin: 'spin' };
const meta = row => ({ blockNumber: String(row.blockNumber), transactionHash: row.transactionHash, logIndex: row.logIndex });

export async function gameReceipt(s, hash, signal, blockHash) {
  if (!s.gameReceipts) s.gameReceipts = new Map();
  if (s.gameReceipts.has(hash)) return s.gameReceipts.get(hash);
  const pending = decodeGameReceipt(s, hash, signal, blockHash); s.gameReceipts.set(hash, pending);
  try { return await pending; } catch(error) { s.gameReceipts.delete(hash); throw error; }
}
async function decodeGameReceipt(s, hash, signal, blockHash) {
  const receipt = await s.client.receipt(hash, signal, blockHash); const iface = await contractInterface('GAME');
  return receipt.logs.filter(log => log.address.toLowerCase() === s.client.address('GAME')).flatMap(log => {
    let parsed; try { parsed = decodeLog(iface, log); } catch { return []; }
    return parsed ? [plainEvent({ ...log, args: parsed.args }, parsed.fragment)] : [];
  });
}
export async function boxLeg(s, row, { receipt, signal } = {}) {
  const a = row.args; const player = a.player;
  const events = receipt ?? await gameReceipt(s, row.transactionHash, signal, row.blockHash);
  // Counted boxes settle several legs in one transaction. The shared order
  // index is common to a player's opening anchors, never a unique box id.
  const anchors = events.filter(e => e.args.player === player && ['LootBoxOpened', 'PresaleBoxOpened'].includes(e.name));
  const indices = new Set(anchors.map(e => Number(e.args.lootboxIndex ?? e.args.index)));
  const ownIndex = a.lootboxIndex ?? (row.name === 'PresaleBoxOpened' ? a.index : null);
  let lootboxIndex = ownIndex != null ? Number(ownIndex) : indices.size === 1 ? [...indices][0] : null;
  if (lootboxIndex == null && row.name === 'BoxSpin') {
    // Spin-only boxes have no LootBoxOpened anchor. A direct openBox call
    // supplies the exact index without guessing from unrelated receipt legs.
    const tx = await s.client.rpc('eth_getTransactionByHash', [row.transactionHash], signal);
    if (tx?.to?.toLowerCase() === s.client.address('GAME')) {
      const decoded = (await contractInterface('GAME')).parseTransaction({ data: tx.input });
      if (decoded?.name === 'openBox' && decoded.args[0].toLowerCase() === player) lootboxIndex = Number(decoded.args[1]);
    }
  }
  const delivery = events.find(e => e.name === 'AfkingDelivered' && e.args.player === player);
  let spin = null;
  if (row.name === 'BoxSpin') {
    const { decodeBoxSpin } = await import('../app/lootbox-legs.js');
    spin = { ...decodeBoxSpin(a.betId, a.packedSpins), payout: a.payout, ethShare: a.ethShare };
  }
  return { uid: `${row.transactionHash}:${row.logIndex}`, source: spin ? 'spin' : 'result', legType: LEG_TYPES[row.name],
    rewardType: RESULT_TYPES[row.name] ?? row.name, player, lootboxIndex, origin: lootboxIndex == null ? null : lootboxIndex === 0 ? 'afking' : 'normal',
    boxAmountRawWei: a.lootboxAmount ?? (['LootBoxOpened', 'PresaleBoxOpened'].includes(row.name) ? a.amount : null),
    afkingSpendRawWei: delivery ? String(BigInt(delivery.args.packed) & ((1n << 128n) - 1n)) : null,
    levelAtOpen: null, rewardData: spin ? null : a, spin, ...meta(row), ord: eventOrdinal(row) };
}

export async function degeneretteItem(s, row, signal) {
  const a = row.args; const player = a.player; const betId = a.betId;
  const [word, results] = await Promise.all([
    s.field('GAME', 'lootboxRngWordByIndex', a.index),
    eventFacts(s, ['DegeneretteResolved', 'DegeneretteResult'], { contract: 'GAME', player, filters: { betId }, fromBlock: row.blockNumber, signal }),
  ]);
  const resolved = results.find(e => e.name === 'DegeneretteResolved');
  const payouts = resolved ? (await gameReceipt(s, resolved.transactionHash, signal, resolved.blockHash)).filter(e => e.args.player === player && BOX_RESULTS.includes(e.name)) : [];
  return { id: eventOrdinal(row), player, betIndex: Number(a.index), betId, packedData: a.packed, ...meta(row),
    rngReady: word !== 0n, rngWord: word ? String(word) : null,
    results: results.map(e => ({ resultType: e.name === 'DegeneretteResolved' ? 'resolved' : 'result', payout: e.args.totalPayout ?? e.args.payout, resultData: e.args, ...meta(e) })),
    // The shared presentation code derives and checks every reel from the RNG
    // word against the emitted score and spin-zero result.
    resultTickets: [], activityBps: Number((BigInt(a.packed) >> 202n) & 0xffffn), activityBreakdown: null,
    lootboxPayouts: payouts.map(e => ({ rewardType: RESULT_TYPES[e.name] ?? e.name, rewardData: e.args, lootboxIndex: e.args.lootboxIndex == null ? null : Number(e.args.lootboxIndex), ...meta(e) })) };
}

export async function readFeedRoute(s, url, { signal } = {}) {
  const path = url.pathname; const q = url.searchParams;
  if (!['/lootbox/feed', '/lootbox/legs', '/lootbox/box-spins', '/degenerette/feed'].includes(path)) return undefined;
  const player = q.has('player') ? playerAddress(q.get('player')) : undefined;
  const names = path === '/degenerette/feed' ? ['DegeneretteBetPlaced'] : path === '/lootbox/feed' ? ['LootBoxBuy', 'PresaleBoxBuy']
    : path === '/lootbox/box-spins' ? ['BoxSpin'] : BOX_RESULTS;
  const page = await eventPage(s, names, url, { contract: 'GAME', player, signal });
  if (path === '/lootbox/feed' && player && q.has('recover')) {
    const { pendingBoxes } = await import('./pending.js');
    const pending = await pendingBoxes(s, player, signal);
    page.rows = [...new Map([...page.rows, ...pending].map(row => [eventOrdinal(row), row])).values()];
  }
  const items = [];
  for (const row of page.rows) {
    checkAbort(signal);
    if (path === '/degenerette/feed') { items.push(await degeneretteItem(s, row, signal)); continue; }
    if (path === '/lootbox/legs' || path === '/lootbox/box-spins') {
      const leg = await boxLeg(s, row, { signal });
      if (q.has('lootboxIndex') && leg.lootboxIndex !== uint(q.get('lootboxIndex'), Number.MAX_SAFE_INTEGER)) continue;
      items.push(path === '/lootbox/box-spins' ? { id: leg.ord, player: leg.player, ...leg.spin, ...meta(row) } : leg); continue;
    }
    const a = row.args; const buyer = a.buyer;
    const [word, pending, openedRows, receipt] = await Promise.all([
      s.field('GAME', 'lootboxRngWordByIndex', a.index),
      s.field('GAME', row.name === 'PresaleBoxBuy' ? 'presaleBoxEth' : 'lootboxOrder', a.index, buyer),
      eventFacts(s, ['LootBoxOpened', 'PresaleBoxOpened'], { contract: 'GAME', player: buyer, filters: { lootboxIndex: a.index, index: a.index }, fromBlock: row.blockNumber, signal }),
      gameReceipt(s, row.transactionHash, signal, row.blockHash),
    ]);
    const boost = receipt.find(e => e.name === 'LootBoxBoostConsumed' && e.args.player === buyer);
    items.push({ id: eventOrdinal(row), player: buyer, kind: 'eth', costRawWei: a.amount,
      boxAmountRawWei: boost?.args.boostedAmount ?? a.amount, boostBps: boost ? Number(boost.args.boostBps) : null,
      resolvedIndex: Number(a.index), ...meta(row), rngReady: word !== 0n, opened: pending === 0n,
      activityBps: pending ? Number((pending >> 24n) & 0x7fffn) : null, activityBreakdown: null,
      results: openedRows.map(e => ({ rewardType: RESULT_TYPES[e.name], rewardData: e.args, blockNumber: String(e.blockNumber), levelAtOpen: null })) });
  }
  return { items, nextCursor: page.nextCursor };
}
